step
    .goto Mulgore,47.0,58.0
    >>В деревне Кровавого Копыта привяжите камень возвращения. Возьмите задания (Dwarven Digging, Mazzranache, Swoop Hunting, Poison Water, Mulgore Plainstriders, Rite of Strength)
